module.exports = [
{ e: "📺", art: { b: "📺", s: ["🔴", "🟢", "🔵", "💧"], c: ["#1B1B3A", "#3A3A8A"] },
pt: { h: "Leo estava tão perto da TV que o vovô pediu para ele se afastar. “Mas eu vi umas listrinhas coloridas lá dentro!”, disse Leo. O vovô achou ótimo: “Então você descobriu os pixels! Toda imagem da tela é feita de pontinhos minúsculos.”", t: "Telas e pixels", f: "As telas de TV, celular e computador são formadas por milhões de pontinhos chamados pixels. Cada pixel tem três luzinhas: vermelha, verde e azul. Misturando essas três cores com mais ou menos brilho, a tela forma todas as cores que vemos.", x: "Uma TV 4K tem mais de 8 milhões de pixels! De longe, nosso olho mistura os pontinhos e enxerga uma imagem lisinha.", s: ["A televisão chegou ao Brasil em 1950, com a TV Tupi, em São Paulo.", "As primeiras TVs eram em preto e branco e tinham telas pequenas e caixas enormes.", "Ficar muito tempo seguido na frente de telas cansa os olhos. Dê pausas e olhe para longe de vez em quando."], ex: { t: "Lupa de gota d'água", m: "um celular ou tablet com a tela ligada numa imagem branca, um conta-gotas ou canudo, água, um plástico transparente (como capinha ou filme plástico)", p: ["Cubra a tela com o plástico transparente, para não molhar o aparelho.", "Pingue uma gotinha de água em cima do plástico, numa parte branca da imagem.", "Olhe pela gota: ela funciona como lupa e mostra as luzinhas vermelhas, verdes e azuis! Seque tudo depois."] }, at: "Pixel art", m: "papel quadriculado, lápis de cor", p: ["Desenhe uma figura pintando só quadradinhos inteiros, como um pixel de cada vez.", "Tente fazer um raio, uma lâmpada ou um gato.", "Olhe o desenho de longe e veja como fica mais lisinho. Pinte a 21ª lâmpada do painel."], q: "Quanto tempo de tela por dia você acha que é saudável?" },
en: { h: "Leo was sitting so close to the TV that Grandpa asked him to back up. “But I saw little colored stripes in there!” Leo said. Grandpa loved that: “Then you've discovered pixels! Every picture on a screen is made of tiny dots.”", t: "Screens and pixels", f: "TV, phone and computer screens are made of millions of tiny dots called pixels. Each pixel has three little lights: red, green and blue. By mixing those three colors at different brightnesses, the screen makes every color we see.", x: "A 4K TV has more than 8 million pixels! From a distance, our eyes blend the dots and see a smooth picture.", s: ["Television arrived in Brazil in 1950, with TV Tupi in São Paulo.", "The first TVs were black and white, with small screens and huge cabinets.", "Staring at screens for a long time tires your eyes. Take breaks and look into the distance now and then."], ex: { t: "Water drop magnifier", m: "a phone or tablet showing a white image, a dropper or straw, water, clear plastic (like a case or plastic wrap)", p: ["Cover the screen with the clear plastic so the device doesn't get wet.", "Place a tiny drop of water on the plastic over a white part of the image.", "Look through the drop: it works like a magnifying glass and shows the little red, green and blue lights! Dry everything afterward."] }, at: "Pixel art", m: "graph paper, colored pencils", p: ["Draw a picture by coloring only whole squares, one pixel at a time.", "Try a lightning bolt, a light bulb or a cat.", "Look at it from far away and see how much smoother it looks. Color the 21st bulb on your chart."], q: "How much screen time a day do you think is healthy?" },
es: { h: "Leo estaba tan cerca de la tele que el abuelo le pidió que se alejara. “¡Pero vi unas rayitas de colores adentro!”, dijo Leo. Al abuelo le encantó: “¡Entonces descubriste los píxeles! Toda imagen de la pantalla está hecha de puntitos diminutos.”", t: "Pantallas y píxeles", f: "Las pantallas de tele, celular y computadora están formadas por millones de puntitos llamados píxeles. Cada píxel tiene tres lucecitas: roja, verde y azul. Mezclando esos tres colores con más o menos brillo, la pantalla forma todos los colores que vemos.", x: "¡Una tele 4K tiene más de 8 millones de píxeles! De lejos, nuestro ojo mezcla los puntitos y ve una imagen lisa.", s: ["La televisión llegó a Brasil en 1950, con TV Tupi, en São Paulo.", "Las primeras teles eran en blanco y negro, con pantallas chiquitas y cajas enormes.", "Pasar mucho tiempo seguido frente a pantallas cansa la vista. Haz pausas y mira a lo lejos de vez en cuando."], ex: { t: "Lupa de gota de agua", m: "un celular o tablet con la pantalla mostrando una imagen blanca, un gotero o pajita, agua, un plástico transparente (como una funda o film)", p: ["Cubre la pantalla con el plástico transparente, para no mojar el aparato.", "Pon una gotita de agua sobre el plástico, en una parte blanca de la imagen.", "Mira a través de la gota: ¡funciona como lupa y muestra las lucecitas rojas, verdes y azules! Seca todo después."] }, at: "Pixel art", m: "papel cuadriculado, lápices de colores", p: ["Dibuja una figura pintando solo cuadraditos enteros, como un píxel por vez.", "Intenta hacer un rayo, una bombilla o un gato.", "Mira el dibujo de lejos y fíjate cómo se ve más liso. Pinta la bombilla 21 del panel."], q: "¿Cuánto tiempo de pantalla por día crees que es saludable?" } },

{ e: "💻", art: { b: "💻", s: ["🔲", "0️⃣", "1️⃣", "🧠"], c: ["#0B3A3A", "#2C8A8A"] },
pt: { h: "Nina pensou num animal, e Leo tentou adivinhar fazendo só perguntas de sim ou não. “Ele voa?” “Não.” “Vive na água?” “Sim.” Em poucas perguntas, ele acertou: “Golfinho!” O vovô bateu palmas: “Vocês brincaram exatamente do jeito que um computador pensa!”", t: "Computadores e chips", f: "Dentro dos computadores e celulares existem chips cheios de transistores, que são interruptores minúsculos que ligam e desligam. Ligado vale 1, desligado vale 0. Combinando bilhões desses sins e nãos, o computador faz contas, mostra vídeos e roda jogos.", x: "O chip de um celular moderno tem bilhões de transistores, e cada um é tão pequeno que milhares deles caberiam na espessura de um fio de cabelo!", s: ["O transistor foi inventado em 1947 e mudou o mundo.", "Um dos primeiros computadores, o ENIAC, de 1945, pesava cerca de 27 toneladas e ocupava uma sala inteira.", "Os chips são feitos principalmente de silício, um material que vem da areia."], ex: { t: "Jogo das 20 perguntas", m: "papel e lápis, um parceiro", p: ["Uma pessoa pensa em qualquer coisa: um animal, um objeto ou um lugar.", "A outra só pode fazer perguntas de sim ou não e anota cada resposta como 1 (sim) ou 0 (não).", "Em quantas perguntas você descobriu? Com 20 perguntas bem feitas, dá para escolher entre mais de um milhão de coisas!"] }, at: "Por dentro do computador", m: "papel, lápis de cor", p: ["Desenhe um computador “aberto” mostrando um chip com uma cidade de caminhos dentro.", "Desenhe os zeros e uns andando pelos caminhos como carrinhos.", "Pinte a 22ª lâmpada do painel."], q: "Que pergunta você faria primeiro no jogo das 20 perguntas?" },
en: { h: "Nina thought of an animal, and Leo tried to guess it by asking only yes-or-no questions. “Does it fly?” “No.” “Does it live in water?” “Yes.” In just a few questions he got it: “A dolphin!” Grandpa clapped: “You just played exactly the way a computer thinks!”", t: "Computers and chips", f: "Inside computers and phones are chips full of transistors, which are tiny switches that turn on and off. On means 1, off means 0. By combining billions of these yeses and nos, the computer does math, shows videos and runs games.", x: "A modern phone chip has billions of transistors, each so small that thousands of them would fit across the width of a hair!", s: ["The transistor was invented in 1947 and changed the world.", "One of the first computers, ENIAC, from 1945, weighed about 27 tons and filled an entire room.", "Chips are made mostly of silicon, a material that comes from sand."], ex: { t: "Twenty questions", m: "paper and pencil, a partner", p: ["One person thinks of anything: an animal, an object or a place.", "The other can only ask yes-or-no questions and writes each answer as 1 (yes) or 0 (no).", "How many questions did it take? With 20 good questions, you can pick out one thing from more than a million!"] }, at: "Inside the computer", m: "paper, colored pencils", p: ["Draw an “opened-up” computer showing a chip with a city of paths inside.", "Draw zeros and ones traveling the paths like little cars.", "Color the 22nd bulb on your chart."], q: "What would be your first question in twenty questions?" },
es: { h: "Nina pensó en un animal, y Leo intentó adivinarlo haciendo solo preguntas de sí o no. “¿Vuela?” “No.” “¿Vive en el agua?” “Sí.” En pocas preguntas acertó: “¡Un delfín!” El abuelo aplaudió: “¡Jugaron exactamente como piensa una computadora!”", t: "Computadoras y chips", f: "Dentro de las computadoras y los celulares hay chips llenos de transistores, que son interruptores diminutos que se prenden y se apagan. Prendido vale 1, apagado vale 0. Combinando miles de millones de esos sí y no, la computadora hace cuentas, muestra videos y hace funcionar juegos.", x: "¡El chip de un celular moderno tiene miles de millones de transistores, y cada uno es tan pequeño que miles cabrían en el grosor de un pelo!", s: ["El transistor se inventó en 1947 y cambió el mundo.", "Una de las primeras computadoras, la ENIAC, de 1945, pesaba unas 27 toneladas y ocupaba una sala entera.", "Los chips están hechos sobre todo de silicio, un material que viene de la arena."], ex: { t: "Juego de las 20 preguntas", m: "papel y lápiz, un compañero", p: ["Una persona piensa en cualquier cosa: un animal, un objeto o un lugar.", "La otra solo puede hacer preguntas de sí o no y anota cada respuesta como 1 (sí) o 0 (no).", "¿En cuántas preguntas lo descubriste? ¡Con 20 preguntas bien hechas se puede elegir entre más de un millón de cosas!"] }, at: "Por dentro de la computadora", m: "papel, lápices de colores", p: ["Dibuja una computadora “abierta” mostrando un chip con una ciudad de caminos adentro.", "Dibuja los ceros y unos viajando por los caminos como autitos.", "Pinta la bombilla 22 del panel."], q: "¿Qué pregunta harías primero en el juego de las 20 preguntas?" } },

{ e: "🔊", art: { b: "🔊", s: ["📱", "🎤", "🧲", "🎵"], c: ["#3A0B3A", "#9A2C9A"] },
pt: { h: "O celular do vovô tocava uma música baixinho, e Leo queria ouvir mais alto. Nina teve uma ideia: colocou o celular dentro de um copo grande. O som ficou mais forte! “Vocês fizeram uma caixa de som sem eletricidade”, disse o vovô. “Mas a de verdade tem um ímã escondido.”", t: "Alto-falantes e microfones", f: "Dentro de um alto-falante há um ímã e uma bobina de fio presa num cone. A eletricidade que chega na bobina muda muito rápido, e ela é empurrada e puxada pelo ímã, fazendo o cone vibrar. Essa vibração empurra o ar e vira som. O microfone faz o contrário: transforma o som em eletricidade.", x: "Os fones de ouvido são alto-falantes minúsculos, cada um com seu próprio ímã!", s: ["Os primeiros telefones já usavam ímãs e bobinas para transformar a voz em eletricidade e de volta em voz.", "Quanto mais rápido o cone vibra, mais agudo é o som.", "Ouça música sempre num volume confortável para proteger os ouvidos."], ex: { t: "Amplificador de copo", m: "um copo grande de plástico ou papel, um rolo de papel-toalha vazio, um celular tocando música, tesoura (com um adulto)", p: ["Com um adulto, corte uma fenda no meio do rolo do tamanho do celular e encaixe o aparelho, com o alto-falante para dentro.", "Faça um furo na lateral de cada copo e encaixe-os nas pontas do rolo, como duas cornetas.", "Toque uma música: o som fica bem mais alto! Os copos guiam e concentram as vibrações do ar."] }, at: "Banda de alto-falantes", m: "papel, lápis de cor", p: ["Desenhe um alto-falante cortado ao meio mostrando o ímã, a bobina e o cone.", "Desenhe ondas de som saindo dele em direção a uma orelha.", "Pinte a 23ª lâmpada do painel."], q: "Qual música você colocaria para tocar no seu amplificador de copo?" },
en: { h: "Grandpa's phone was playing a song very quietly, and Leo wanted it louder. Nina had an idea: she put the phone inside a big cup. The sound got stronger! “You made a speaker without electricity,” said Grandpa. “But a real one has a hidden magnet.”", t: "Speakers and microphones", f: "Inside a speaker are a magnet and a coil of wire attached to a cone. The electricity reaching the coil changes very fast, so the magnet pushes and pulls the coil, making the cone vibrate. That vibration pushes the air and becomes sound. A microphone does the opposite: it turns sound into electricity.", x: "Earbuds are tiny speakers, each with its own magnet!", s: ["The first telephones already used magnets and coils to turn a voice into electricity and back into a voice.", "The faster the cone vibrates, the higher the sound.", "Always listen to music at a comfortable volume to protect your ears."], ex: { t: "Cup amplifier", m: "two large plastic or paper cups, an empty paper towel roll, a phone playing music, scissors (with a grown-up)", p: ["With a grown-up, cut a slot in the middle of the roll the size of the phone and slide the phone in, speaker facing inward.", "Cut a hole in the side of each cup and fit them onto the ends of the roll, like two horns.", "Play a song: it's much louder! The cups guide and focus the air's vibrations."] }, at: "Speaker band", m: "paper, colored pencils", p: ["Draw a speaker cut in half showing the magnet, the coil and the cone.", "Draw sound waves coming out of it toward an ear.", "Color the 23rd bulb on your chart."], q: "What song would you play on your cup amplifier?" },
es: { h: "El celular del abuelo tocaba una canción bajito, y Leo quería oírla más fuerte. Nina tuvo una idea: puso el celular dentro de un vaso grande. ¡El sonido se hizo más fuerte! “Hicieron un parlante sin electricidad”, dijo el abuelo. “Pero uno de verdad tiene un imán escondido.”", t: "Parlantes y micrófonos", f: "Dentro de un parlante hay un imán y una bobina de cable pegada a un cono. La electricidad que llega a la bobina cambia muy rápido, y el imán la empuja y la atrae, haciendo vibrar el cono. Esa vibración empuja el aire y se convierte en sonido. El micrófono hace lo contrario: transforma el sonido en electricidad.", x: "¡Los auriculares son parlantes diminutos, cada uno con su propio imán!", s: ["Los primeros teléfonos ya usaban imanes y bobinas para transformar la voz en electricidad y de nuevo en voz.", "Cuanto más rápido vibra el cono, más agudo es el sonido.", "Escucha música siempre a un volumen cómodo para proteger tus oídos."], ex: { t: "Amplificador de vasos", m: "dos vasos grandes de plástico o papel, un tubo de papel de cocina vacío, un celular con música, tijera (con un adulto)", p: ["Con un adulto, corta una ranura en el medio del tubo del tamaño del celular y encaja el aparato, con el parlante hacia adentro.", "Haz un agujero al costado de cada vaso y encájalos en las puntas del tubo, como dos cornetas.", "Pon una canción: ¡suena mucho más fuerte! Los vasos guían y concentran las vibraciones del aire."] }, at: "Banda de parlantes", m: "papel, lápices de colores", p: ["Dibuja un parlante cortado al medio mostrando el imán, la bobina y el cono.", "Dibuja ondas de sonido saliendo de él hacia una oreja.", "Pinta la bombilla 23 del panel."], q: "¿Qué canción pondrías en tu amplificador de vasos?" } },

{ e: "🦈", art: { b: "🦈", s: ["🐝", "🌸", "🦆", "⚡"], c: ["#0B2A4E", "#2C6AB0"] },
pt: { h: "No aquário, Leo viu um tubarão deslizando bem devagar e perguntou como ele achava comida no escuro do fundo do mar. “Ele sente a eletricidade dos outros animais”, contou o vovô. Nina achou que era invenção, até o vovô mostrar no livro.", t: "Animais que sentem eletricidade", f: "Todo ser vivo produz um pouquinho de eletricidade quando mexe os músculos. Alguns animais conseguem sentir isso! Os tubarões têm pontinhos no focinho, cheios de sensores, que percebem a eletricidade de peixes escondidos na areia. O ornitorrinco usa o bico para sentir a eletricidade de bichinhos no fundo dos rios.", x: "As abelhas ficam carregadas de eletricidade estática quando voam, e as flores têm carga oposta. Cientistas descobriram que as abelhas conseguem sentir o “campo elétrico” das flores!", s: ["Os sensores elétricos dos tubarões se chamam ampolas de Lorenzini.", "A eletricidade estática das abelhas ajuda o pólen a grudar no corpo delas.", "Alguns peixes da Amazônia usam pulsos elétricos fraquinhos para se orientar e conversar entre si."], ex: { t: "Pólen grudento", m: "um prato, uma colher de sal, uma pitada de pimenta-do-reino moída (ou papel picadinho), uma bexiga, cabelo seco", p: ["Misture o sal com a pimenta no prato.", "Esfregue a bexiga no cabelo seco por uns 10 segundos.", "Passe a bexiga devagar um pouquinho acima da mistura: a pimenta pula e gruda na bexiga, e o sal fica! É parecido com o pólen grudando nas abelhas."] }, at: "Superpoder elétrico", m: "papel, lápis de cor", p: ["Desenhe um tubarão, um ornitorrinco e uma abelha com raiozinhos mostrando o que eles sentem.", "Invente um animal com um superpoder elétrico novo.", "Pinte a 24ª lâmpada do painel."], q: "Se você pudesse sentir eletricidade como um tubarão, o que descobriria na sua casa?" },
en: { h: "At the aquarium, Leo watched a shark glide slowly by and asked how it found food in the dark depths of the sea. “It senses the electricity of other animals,” Grandpa said. Nina thought he was making it up until he showed her in a book.", t: "Animals that sense electricity", f: "Every living thing makes a tiny bit of electricity when it moves its muscles. Some animals can sense it! Sharks have little pores on their snouts full of sensors that detect the electricity of fish hiding in the sand. The platypus uses its bill to sense the electricity of little creatures at the bottom of rivers.", x: "Bees build up static electricity as they fly, and flowers have the opposite charge. Scientists discovered that bees can sense flowers' “electric fields”!", s: ["A shark's electric sensors are called ampullae of Lorenzini.", "Bees' static electricity helps pollen stick to their bodies.", "Some Amazon fish use weak electric pulses to find their way and communicate with each other."], ex: { t: "Sticky pollen", m: "a plate, a spoonful of salt, a pinch of ground black pepper (or tiny bits of paper), a balloon, dry hair", p: ["Mix the salt and pepper on the plate.", "Rub the balloon on dry hair for about 10 seconds.", "Slowly pass the balloon just above the mixture: the pepper jumps up and sticks to the balloon, and the salt stays! It's similar to pollen sticking to bees."] }, at: "Electric superpower", m: "paper, colored pencils", p: ["Draw a shark, a platypus and a bee with little lightning bolts showing what they sense.", "Invent an animal with a new electric superpower.", "Color the 24th bulb on your chart."], q: "If you could sense electricity like a shark, what would you discover in your house?" },
es: { h: "En el acuario, Leo vio un tiburón deslizándose despacito y preguntó cómo encontraba comida en la oscuridad del fondo del mar. “Siente la electricidad de los otros animales”, contó el abuelo. Nina pensó que era un invento, hasta que el abuelo se lo mostró en un libro.", t: "Animales que sienten la electricidad", f: "Todo ser vivo produce un poquito de electricidad cuando mueve los músculos. ¡Algunos animales pueden sentirla! Los tiburones tienen puntitos en el hocico, llenos de sensores, que perciben la electricidad de peces escondidos en la arena. El ornitorrinco usa el pico para sentir la electricidad de bichitos en el fondo de los ríos.", x: "¡Las abejas se cargan de electricidad estática al volar, y las flores tienen carga opuesta. Los científicos descubrieron que las abejas pueden sentir el “campo eléctrico” de las flores!", s: ["Los sensores eléctricos de los tiburones se llaman ampollas de Lorenzini.", "La electricidad estática de las abejas ayuda a que el polen se pegue a su cuerpo.", "Algunos peces de la Amazonía usan pulsos eléctricos débiles para orientarse y comunicarse entre sí."], ex: { t: "Polen pegajoso", m: "un plato, una cucharada de sal, una pizca de pimienta negra molida (o papelitos picados), un globo, pelo seco", p: ["Mezcla la sal con la pimienta en el plato.", "Frota el globo en el pelo seco unos 10 segundos.", "Pasa el globo despacio un poquito por encima de la mezcla: ¡la pimienta salta y se pega al globo, y la sal se queda! Es parecido al polen pegándose a las abejas."] }, at: "Superpoder eléctrico", m: "papel, lápices de colores", p: ["Dibuja un tiburón, un ornitorrinco y una abeja con rayitos que muestren lo que sienten.", "Inventa un animal con un superpoder eléctrico nuevo.", "Pinta la bombilla 24 del panel."], q: "Si pudieras sentir la electricidad como un tiburón, ¿qué descubrirías en tu casa?" } },

{ e: "🔥", art: { b: "🚿", s: ["🍞", "🔥", "♨️", "👐"], c: ["#5A1B0B", "#E0502C"] },
pt: { h: "Depois do banho quentinho, Leo perguntou como o chuveiro esquentava a água tão rápido. “Dentro dele tem um fio especial que esquenta quando a eletricidade passa”, explicou o vovô. “A torradeira, o ferro de passar e o secador funcionam do mesmo jeito.”", t: "Eletricidade que vira calor", f: "Quando a eletricidade passa por certos fios, eles “reclamam” e esquentam. Esses fios se chamam resistências. O chuveiro elétrico, a torradeira, o ferro de passar e o forno elétrico usam resistências para transformar eletricidade em calor.", x: "O chuveiro elétrico é muito mais comum no Brasil do que na maioria dos países! Em muitos lugares do mundo, a água do banho é aquecida por gás ou em grandes tanques.", s: ["O chuveiro elétrico é um dos aparelhos que mais gastam energia numa casa brasileira, por isso banhos curtos ajudam muito.", "Nas lâmpadas antigas, o filamento esquentava tanto que ficava branco de brilho.", "A energia nunca some: ela só muda de forma, de eletricidade para calor, luz ou movimento."], ex: { t: "Elástico que esquenta", m: "um elástico largo, as suas mãos", p: ["Encoste o elástico relaxado na testa e sinta a temperatura.", "Estique o elástico bem rápido várias vezes e encoste de novo na testa.", "Ele ficou mais quentinho! Esfregue as mãos rápido também: o movimento vira calor. Na resistência, é a eletricidade que vira calor."] }, at: "Desafio do banho curto", m: "um relógio ou ampulheta, papel, lápis", p: ["Cronometre quanto tempo dura o seu banho normal.", "Tente um banho mais curto, de uns 5 minutos, com uma música de 5 minutos tocando.", "Anote a diferença durante uma semana e pinte a 25ª lâmpada do painel."], q: "Que outros aparelhos da sua casa esquentam com eletricidade?" },
en: { h: "After a nice hot shower, Leo asked how the electric showerhead heated the water so fast. “Inside it there's a special wire that heats up when electricity runs through it,” Grandpa explained. “Toasters, irons and hair dryers work the same way.”", t: "Electricity that turns into heat", f: "When electricity passes through certain wires, they resist and heat up. These wires are called heating elements. Electric showerheads, toasters, irons and electric ovens use them to turn electricity into heat.", x: "Electric showerheads are much more common in Brazil than in most countries! In many places, shower water is heated by gas or in large tanks.", s: ["The electric shower is one of the biggest energy users in a Brazilian home, so short showers help a lot.", "In old light bulbs, the filament got so hot it glowed white.", "Energy never disappears: it just changes form, from electricity to heat, light or motion."], ex: { t: "The rubber band that warms up", m: "a wide rubber band, your hands", p: ["Touch the relaxed rubber band to your forehead and feel its temperature.", "Stretch the band quickly several times and touch it to your forehead again.", "It got warmer! Rub your hands together fast too: motion turns into heat. In a heating element, it's electricity that turns into heat."] }, at: "Short shower challenge", m: "a clock or sand timer, paper, pencil", p: ["Time how long your usual shower lasts.", "Try a shorter shower, about 5 minutes, with a 5-minute song playing.", "Write down the difference for a week and color the 25th bulb on your chart."], q: "What other devices in your house heat up with electricity?" },
es: { h: "Después de una ducha calentita, Leo preguntó cómo la ducha eléctrica calentaba el agua tan rápido. “Adentro tiene un cable especial que se calienta cuando pasa la electricidad”, explicó el abuelo. “La tostadora, la plancha y el secador funcionan igual.”", t: "Electricidad que se vuelve calor", f: "Cuando la electricidad pasa por ciertos cables, estos “se quejan” y se calientan. Esos cables se llaman resistencias. La ducha eléctrica, la tostadora, la plancha y el horno eléctrico usan resistencias para transformar electricidad en calor.", x: "¡La ducha eléctrica es mucho más común en Brasil que en la mayoría de los países! En muchos lugares del mundo, el agua del baño se calienta con gas o en grandes tanques.", s: ["La ducha eléctrica es uno de los aparatos que más energía gastan en una casa brasileña, por eso las duchas cortas ayudan mucho.", "En las bombillas antiguas, el filamento se calentaba tanto que brillaba blanco.", "La energía nunca desaparece: solo cambia de forma, de electricidad a calor, luz o movimiento."], ex: { t: "La gomita que se calienta", m: "una gomita elástica ancha, tus manos", p: ["Apoya la gomita floja en tu frente y siente la temperatura.", "Estírala muy rápido varias veces y vuelve a apoyarla en la frente.", "¡Se puso más calentita! Frótate las manos rápido también: el movimiento se vuelve calor. En la resistencia, es la electricidad la que se vuelve calor."] }, at: "Desafío de la ducha corta", m: "un reloj o reloj de arena, papel, lápiz", p: ["Cronometra cuánto dura tu ducha normal.", "Intenta una ducha más corta, de unos 5 minutos, con una canción de 5 minutos sonando.", "Anota la diferencia durante una semana y pinta la bombilla 25 del panel."], q: "¿Qué otros aparatos de tu casa se calientan con electricidad?" } },

{ e: "🧛", art: { b: "🔌", s: ["🧛", "📺", "🔋", "🌍"], c: ["#1B3A1B", "#3A8A3A"] },
pt: { h: "À noite, com tudo apagado, Leo viu várias luzinhas vermelhas acesas pela casa: na TV, no micro-ondas, no carregador. “São vampiros de energia!”, brincou o vovô. “Mesmo desligados, eles continuam chupando um pouquinho de eletricidade.” Nina decidiu caçar todos.", t: "Economizando energia", f: "Produzir eletricidade custa dinheiro e, muitas vezes, afeta a natureza. Por isso é importante não desperdiçar. Apagar a luz ao sair do quarto, tirar carregadores da tomada, abrir a geladeira só o necessário e tomar banhos curtos fazem diferença.", x: "Os aparelhos em modo de espera, com aquela luzinha acesa, podem gastar uma parte da energia de uma casa, mesmo sem ninguém usá-los!", s: ["Aproveitar a luz do sol durante o dia é um jeito simples de economizar.", "Deixar a porta da geladeira aberta faz o motor dela trabalhar muito mais.", "Lâmpadas de LED e aparelhos com selo de eficiência gastam menos energia."], ex: { t: "Caça aos vampiros", m: "papel, lápis, uma lanterna, um adulto", p: ["À noite, com as luzes apagadas, percorra a casa com um adulto procurando luzinhas acesas de aparelhos “desligados”.", "Anote cada vampiro encontrado: TV, micro-ondas, carregador…", "Com o adulto, decidam quais podem ser tirados da tomada quando ninguém estiver usando."] }, at: "Guardião da energia", m: "papel, lápis de cor, fita", p: ["Faça plaquinhas para colar perto dos interruptores: “Saiu? Apague!”.", "Desenhe um crachá de “Guardião da Energia” para usar durante a semana.", "Pinte a 26ª lâmpada do painel."], q: "Qual hábito de economia de energia a sua família pode começar hoje?" },
en: { h: "At night, with everything off, Leo saw lots of little red lights glowing around the house: on the TV, the microwave, the charger. “They're energy vampires!” Grandpa joked. “Even switched off, they keep sipping a little electricity.” Nina decided to hunt them all down.", t: "Saving energy", f: "Making electricity costs money and often affects nature. That's why it's important not to waste it. Turning off the light when you leave a room, unplugging chargers, opening the fridge only when needed and taking short showers all make a difference.", x: "Devices on standby, with that little light on, can use up part of a home's energy even when nobody's using them!", s: ["Using sunlight during the day is a simple way to save.", "Leaving the fridge door open makes its motor work much harder.", "LED bulbs and appliances with energy-efficiency labels use less energy."], ex: { t: "Vampire hunt", m: "paper, pencil, a flashlight, a grown-up", p: ["At night, with the lights off, walk through the house with a grown-up looking for little lights on “turned-off” devices.", "Write down every vampire you find: TV, microwave, charger…", "With the grown-up, decide which ones can be unplugged when no one's using them."] }, at: "Energy guardian", m: "paper, colored pencils, tape", p: ["Make little signs to stick near light switches: “Leaving? Lights off!”", "Draw an “Energy Guardian” badge to wear during the week.", "Color the 26th bulb on your chart."], q: "What energy-saving habit can your family start today?" },
es: { h: "A la noche, con todo apagado, Leo vio varias lucecitas rojas encendidas por la casa: en la tele, en el microondas, en el cargador. “¡Son vampiros de energía!”, bromeó el abuelo. “Aunque estén apagados, siguen chupando un poquito de electricidad.” Nina decidió cazarlos a todos.", t: "Ahorrando energía", f: "Producir electricidad cuesta dinero y muchas veces afecta a la naturaleza. Por eso es importante no desperdiciarla. Apagar la luz al salir del cuarto, desenchufar los cargadores, abrir la heladera solo lo necesario y bañarse rápido hacen la diferencia.", x: "¡Los aparatos en modo de espera, con esa lucecita encendida, pueden gastar una parte de la energía de una casa aunque nadie los use!", s: ["Aprovechar la luz del sol durante el día es una forma simple de ahorrar.", "Dejar la puerta de la heladera abierta hace que su motor trabaje mucho más.", "Las bombillas LED y los aparatos con etiqueta de eficiencia gastan menos energía."], ex: { t: "Caza de vampiros", m: "papel, lápiz, una linterna, un adulto", p: ["A la noche, con las luces apagadas, recorre la casa con un adulto buscando lucecitas encendidas en aparatos “apagados”.", "Anota cada vampiro que encuentres: tele, microondas, cargador…", "Con el adulto, decidan cuáles se pueden desenchufar cuando nadie los usa."] }, at: "Guardián de la energía", m: "papel, lápices de colores, cinta", p: ["Haz carteles para pegar cerca de los interruptores: “¿Te vas? ¡Apaga!”.", "Dibuja una credencial de “Guardián de la Energía” para usar durante la semana.", "Pinta la bombilla 26 del panel."], q: "¿Qué hábito de ahorro de energía puede empezar tu familia hoy?" } },

{ e: "🧑‍🔬", art: { b: "🧑‍🔬", s: ["⚡", "🧲", "📚", "🌩️"], c: ["#2A1B4E", "#6A3AB0"] },
pt: { h: "Nina leu num livro sobre uma tal “guerra das correntes” e ficou curiosa: “Teve guerra de eletricidade?”. O vovô riu: “Foi uma briga de ideias entre dois inventores famosos. E antes deles, um menino pobre que encadernava livros descobriu quase tudo o que usamos hoje.”", t: "Faraday, Tesla e a guerra das correntes", f: "Michael Faraday descobriu como gerar eletricidade com ímãs e inventou o primeiro motor elétrico simples. Depois, no fim dos anos 1800, Thomas Edison defendia a corrente contínua, e Nikola Tesla defendia a corrente alternada. A alternada venceu, porque viaja melhor por longas distâncias, e é a que chega às nossas casas.", x: "Faraday adorava ensinar crianças: ele criou palestras de Natal sobre ciência para jovens em Londres, e essas palestras acontecem até hoje, quase 200 anos depois!", s: ["Na corrente contínua, os elétrons andam sempre no mesmo sentido, como nas pilhas.", "Na corrente alternada, eles vão e voltam muitas vezes por segundo, como na tomada.", "Tesla também imaginou transmitir energia sem fios, uma ideia que hoje aparece nos carregadores sem fio."], ex: { t: "Detector de eletricidade estática", m: "um pote de vidro com tampa de plástico, um clipe grande, papel-alumínio, uma bexiga, um adulto", p: ["Desdobre o clipe em forma de gancho e, com um adulto, atravesse a tampa com ele. Pendure no gancho duas tirinhas de papel-alumínio bem leves.", "Faça uma bolinha de alumínio na ponta de cima do clipe, por fora da tampa, e feche o pote.", "Esfregue a bexiga no cabelo e aproxime da bolinha: as tirinhas lá dentro se afastam! Elas ficaram com a mesma carga e se empurram."] }, at: "Cartas de cientistas", m: "cartolina, tesoura, lápis de cor", p: ["Faça cartas de jogo para Tales, Franklin, Volta, Ørsted, Faraday, Edison, Tesla e Landell de Moura.", "Escreva em cada carta a maior descoberta de cada um.", "Jogue com a família, tentando adivinhar quem é pela pista, e pinte a 27ª lâmpada do painel."], q: "Qual cientista da eletricidade você gostaria de conhecer? O que perguntaria?" },
en: { h: "Nina read in a book about a “war of the currents” and got curious: “There was an electricity war?” Grandpa laughed: “It was a battle of ideas between two famous inventors. And before them, a poor boy who bound books discovered almost everything we use today.”", t: "Faraday, Tesla and the war of the currents", f: "Michael Faraday discovered how to make electricity with magnets and built the first simple electric motor. Later, in the late 1800s, Thomas Edison championed direct current and Nikola Tesla championed alternating current. Alternating current won because it travels better over long distances, and it's the kind that reaches our homes.", x: "Faraday loved teaching children: he started Christmas science lectures for young people in London, and they still happen today, almost 200 years later!", s: ["In direct current, electrons always flow in the same direction, like in batteries.", "In alternating current, they go back and forth many times per second, like in wall outlets.", "Tesla also imagined sending power without wires, an idea that shows up today in wireless chargers."], ex: { t: "Static electricity detector", m: "a glass jar with a plastic lid, a large paper clip, aluminum foil, a balloon, a grown-up", p: ["Unbend the paper clip into a hook and, with a grown-up, push it through the lid. Hang two very light strips of foil from the hook.", "Make a little foil ball on the top end of the clip, outside the lid, and close the jar.", "Rub the balloon on your hair and bring it near the ball: the strips inside spread apart! They got the same charge and push each other away."] }, at: "Scientist cards", m: "poster board, scissors, colored pencils", p: ["Make playing cards for Thales, Franklin, Volta, Ørsted, Faraday, Edison, Tesla and Landell de Moura.", "On each card, write that person's biggest discovery.", "Play with your family, guessing who it is from the clue, and color the 27th bulb on your chart."], q: "Which electricity scientist would you like to meet? What would you ask?" },
es: { h: "Nina leyó en un libro sobre una tal “guerra de las corrientes” y se puso curiosa: “¿Hubo una guerra de electricidad?”. El abuelo se rió: “Fue una pelea de ideas entre dos inventores famosos. Y antes de ellos, un niño pobre que encuadernaba libros descubrió casi todo lo que usamos hoy.”", t: "Faraday, Tesla y la guerra de las corrientes", f: "Michael Faraday descubrió cómo generar electricidad con imanes e inventó el primer motor eléctrico simple. Después, a fines del siglo XIX, Thomas Edison defendía la corriente continua, y Nikola Tesla la corriente alterna. Ganó la alterna, porque viaja mejor por largas distancias, y es la que llega a nuestras casas.", x: "¡A Faraday le encantaba enseñar a los niños: creó charlas de Navidad sobre ciencia para jóvenes en Londres, y esas charlas se siguen haciendo hoy, casi 200 años después!", s: ["En la corriente continua, los electrones van siempre en el mismo sentido, como en las pilas.", "En la corriente alterna, van y vienen muchas veces por segundo, como en el enchufe.", "Tesla también imaginó transmitir energía sin cables, una idea que hoy aparece en los cargadores inalámbricos."], ex: { t: "Detector de electricidad estática", m: "un frasco de vidrio con tapa de plástico, un clip grande, papel de aluminio, un globo, un adulto", p: ["Estira el clip en forma de gancho y, con un adulto, atraviesa la tapa con él. Cuelga del gancho dos tiritas de aluminio bien livianas.", "Haz una bolita de aluminio en la punta de arriba del clip, por fuera de la tapa, y cierra el frasco.", "Frota el globo en tu pelo y acércalo a la bolita: ¡las tiritas de adentro se separan! Quedaron con la misma carga y se empujan."] }, at: "Cartas de científicos", m: "cartulina, tijera, lápices de colores", p: ["Haz cartas de juego para Tales, Franklin, Volta, Ørsted, Faraday, Edison, Tesla y Landell de Moura.", "Escribe en cada carta el mayor descubrimiento de cada uno.", "Jueguen en familia adivinando quién es por la pista, y pinta la bombilla 27 del panel."], q: "¿Qué científico de la electricidad te gustaría conocer? ¿Qué le preguntarías?" } },

{ e: "🕯️", art: { b: "🕯️", s: ["🚂", "💡", "🏙️", "📜"], c: ["#3A2A0B", "#A07A2C"] },
pt: { h: "O vovô contou que, quando a avó dele era menina, a casa dela no interior ainda não tinha luz elétrica. “Ela fazia a lição com lampião de querosene”, disse. Nina e Leo resolveram fazer um desafio: passar uma hora à noite sem usar nada elétrico.", t: "A eletricidade chega ao Brasil", f: "Em 1879, o imperador Dom Pedro II inaugurou a iluminação elétrica numa estação de trem no Rio de Janeiro. Em 1883, Campos dos Goytacazes, no estado do Rio, foi a primeira cidade da América do Sul a ter iluminação pública elétrica nas ruas.", x: "Até poucas décadas atrás, milhões de brasileiros, principalmente no campo, ainda não tinham luz em casa. Programas de eletrificação levaram energia a muitas dessas famílias nos anos 2000!", s: ["Antes da luz elétrica, as ruas eram iluminadas por lampiões a gás ou a óleo, acesos um por um ao anoitecer.", "Os primeiros bondes elétricos começaram a circular no Rio de Janeiro no fim dos anos 1800.", "Ainda hoje, algumas comunidades isoladas da Amazônia recebem energia de painéis solares."], ex: { t: "Uma hora sem eletricidade", m: "uma vela em suporte seguro ou uma lanterna, jogos de tabuleiro, livros, um adulto", p: ["Combine com a família: uma hora à noite sem TV, celular, luz elétrica ou outros aparelhos (geladeira continua ligada!).", "Usem lanterna ou uma vela sempre com um adulto do lado, e brinquem, conversem ou leiam.", "No final, conversem: o que foi mais difícil? O que foi mais gostoso? Anotem tudo."] }, at: "Entrevista com os mais velhos", m: "papel, lápis", p: ["Pergunte a um avô, avó ou vizinho mais velho como era a vida quando eram crianças.", "Pergunte: tinha TV? Telefone? Como era a luz da casa?", "Escreva as respostas, desenhe a casa antiga e pinte a 28ª lâmpada do painel."], q: "O que você mais gostou na hora sem eletricidade?" },
en: { h: "Grandpa said that when his grandmother was a girl, her house in the countryside still didn't have electric light. “She did her homework by kerosene lamp,” he said. Nina and Leo decided to take on a challenge: spend one hour at night without using anything electric.", t: "Electricity comes to Brazil", f: "In 1879, Emperor Dom Pedro II opened electric lighting at a train station in Rio de Janeiro. In 1883, Campos dos Goytacazes, in the state of Rio, became the first city in South America with electric street lighting.", x: "Until just a few decades ago, millions of Brazilians, especially in rural areas, still had no electricity at home. Electrification programs brought power to many of those families in the 2000s!", s: ["Before electric light, streets were lit by gas or oil lamps, lit one by one at dusk.", "The first electric streetcars began running in Rio de Janeiro in the late 1800s.", "Even today, some isolated communities in the Amazon get their power from solar panels."], ex: { t: "One hour without electricity", m: "a candle in a safe holder or a flashlight, board games, books, a grown-up", p: ["Agree with your family: one hour at night with no TV, phones, electric lights or other devices (the fridge stays on!).", "Use a flashlight, or a candle only with a grown-up right there, and play, talk or read.", "Afterward, talk about it: what was hardest? What was most fun? Write it all down."] }, at: "Interview an elder", m: "paper, pencil", p: ["Ask a grandparent or older neighbor what life was like when they were kids.", "Ask: did they have TV? A telephone? What lit their house?", "Write down the answers, draw their old house and color the 28th bulb on your chart."], q: "What did you like most about the hour without electricity?" },
es: { h: "El abuelo contó que, cuando su abuela era niña, su casa en el campo todavía no tenía luz eléctrica. “Hacía la tarea con una lámpara de queroseno”, dijo. Nina y Leo decidieron hacer un desafío: pasar una hora a la noche sin usar nada eléctrico.", t: "La electricidad llega a Brasil", f: "En 1879, el emperador Don Pedro II inauguró la iluminación eléctrica en una estación de tren de Río de Janeiro. En 1883, Campos dos Goytacazes, en el estado de Río, fue la primera ciudad de América del Sur con alumbrado público eléctrico en las calles.", x: "¡Hasta hace pocas décadas, millones de personas en el campo de América Latina todavía no tenían luz en casa. Programas de electrificación llevaron energía a muchas de esas familias en los años 2000!", s: ["Antes de la luz eléctrica, las calles se iluminaban con faroles a gas o a aceite, encendidos uno por uno al anochecer.", "Los primeros tranvías eléctricos empezaron a circular en Río de Janeiro a fines del siglo XIX.", "Todavía hoy, algunas comunidades aisladas de la Amazonía reciben energía de paneles solares."], ex: { t: "Una hora sin electricidad", m: "una vela en un soporte seguro o una linterna, juegos de mesa, libros, un adulto", p: ["Acuerden en familia: una hora a la noche sin tele, celular, luz eléctrica ni otros aparatos (¡la heladera sigue encendida!).", "Usen linterna, o una vela siempre con un adulto al lado, y jueguen, conversen o lean.", "Al final, conversen: ¿qué fue lo más difícil? ¿Qué fue lo más lindo? Anoten todo."] }, at: "Entrevista a los mayores", m: "papel, lápiz", p: ["Pregúntale a un abuelo, abuela o vecino mayor cómo era la vida cuando eran niños.", "Pregunta: ¿tenían tele? ¿Teléfono? ¿Cómo era la luz de la casa?", "Escribe las respuestas, dibuja la casa antigua y pinta la bombilla 28 del panel."], q: "¿Qué fue lo que más te gustó de la hora sin electricidad?" } },

{ e: "🔮", art: { b: "🔮", s: ["🔋", "📲", "☀️", "🌐"], c: ["#0B2A4E", "#2C8AD4"] },
pt: { h: "Leo colocou o celular do vovô em cima de uma base, sem fio nenhum, e ele começou a carregar. “É mágica!”, disse. “É magnetismo”, corrigiu o vovô, rindo. “E os cientistas estão inventando coisas ainda mais incríveis para o futuro da energia.”", t: "O futuro da eletricidade", f: "Os carregadores sem fio usam ímãs e bobinas: um campo magnético que muda cria eletricidade no celular, sem encostar fios. No futuro, cientistas querem baterias que carregam em minutos, redes de energia inteligentes e até usinas que imitam a energia do Sol, chamadas de fusão nuclear.", x: "Guardar energia é um dos maiores desafios: o sol não brilha à noite e o vento nem sempre sopra. Por isso cientistas do mundo inteiro estudam baterias gigantes e novas formas de armazenar eletricidade!", s: ["Alguns materiais, quando ficam muito frios, deixam a eletricidade passar sem nenhuma perda. Eles se chamam supercondutores.", "As baterias de lítio, usadas nos celulares, renderam o Prêmio Nobel de Química de 2019 a seus inventores.", "Casas do futuro podem produzir a própria energia com o sol e guardar o que sobra."], ex: { t: "Carretel que anda sozinho", m: "um carretel de linha vazio, um elástico, um palito de fósforo usado ou pedaço de palito, um lápis, fita", p: ["Passe o elástico pelo furo do carretel. Prenda uma ponta com o pedacinho de palito e fita de um lado.", "Do outro lado, passe o lápis pela alça do elástico e gire o lápis muitas vezes, enrolando o elástico.", "Coloque no chão e solte: o carretel anda sozinho! A energia ficou guardada no elástico, como numa bateria."] }, at: "Casa do futuro", m: "papel grande, lápis de cor", p: ["Desenhe uma casa que produz a própria energia, com painéis solares, uma bateria e um carregador sem fio.", "Mostre com setas para onde a energia vai durante o dia e durante a noite.", "Pinte a 29ª lâmpada do painel."], q: "Que invenção de energia você gostaria que existisse quando você crescer?" },
en: { h: "Leo set Grandpa's phone on a pad with no wires at all, and it started charging. “It's magic!” he said. “It's magnetism,” Grandpa corrected, laughing. “And scientists are inventing even more amazing things for the future of energy.”", t: "The future of electricity", f: "Wireless chargers use magnets and coils: a changing magnetic field creates electricity in the phone without any wires touching. In the future, scientists want batteries that charge in minutes, smart power grids and even power plants that copy the Sun's energy, called nuclear fusion.", x: "Storing energy is one of the biggest challenges: the sun doesn't shine at night and the wind doesn't always blow. That's why scientists everywhere are studying giant batteries and new ways to store electricity!", s: ["Some materials, when they get very cold, let electricity flow with no loss at all. They're called superconductors.", "Lithium batteries, used in phones, earned their inventors the 2019 Nobel Prize in Chemistry.", "Homes of the future may make their own energy from the sun and store what's left over."], ex: { t: "The self-rolling spool", m: "an empty thread spool, a rubber band, a used matchstick or piece of a stick, a pencil, tape", p: ["Thread the rubber band through the spool's hole. Hold one end in place on one side with the little stick and tape.", "On the other side, slip the pencil through the rubber band loop and turn it many times, winding the band.", "Set it on the floor and let go: the spool rolls by itself! The energy was stored in the rubber band, like in a battery."] }, at: "House of the future", m: "large paper, colored pencils", p: ["Draw a house that makes its own energy, with solar panels, a battery and a wireless charger.", "Show with arrows where the energy goes during the day and at night.", "Color the 29th bulb on your chart."], q: "What energy invention would you like to exist when you grow up?" },
es: { h: "Leo puso el celular del abuelo sobre una base, sin ningún cable, y empezó a cargarse. “¡Es magia!”, dijo. “Es magnetismo”, lo corrigió el abuelo, riéndose. “Y los científicos están inventando cosas todavía más increíbles para el futuro de la energía.”", t: "El futuro de la electricidad", f: "Los cargadores inalámbricos usan imanes y bobinas: un campo magnético que cambia crea electricidad en el celular, sin cables que se toquen. En el futuro, los científicos quieren baterías que se carguen en minutos, redes de energía inteligentes y hasta centrales que imiten la energía del Sol, llamadas de fusión nuclear.", x: "¡Guardar energía es uno de los mayores desafíos: el sol no brilla de noche y el viento no siempre sopla. Por eso científicos de todo el mundo estudian baterías gigantes y nuevas formas de almacenar electricidad!", s: ["Algunos materiales, cuando se enfrían muchísimo, dejan pasar la electricidad sin ninguna pérdida. Se llaman superconductores.", "Las baterías de litio, usadas en los celulares, les dieron a sus inventores el Premio Nobel de Química de 2019.", "Las casas del futuro podrían producir su propia energía con el sol y guardar lo que sobra."], ex: { t: "El carretel que anda solo", m: "un carretel de hilo vacío, una gomita elástica, un fósforo usado o pedacito de palito, un lápiz, cinta", p: ["Pasa la gomita por el agujero del carretel. Sujeta una punta de un lado con el pedacito de palito y cinta.", "Del otro lado, pasa el lápiz por la vuelta de la gomita y gíralo muchas veces, enrollando la gomita.", "Ponlo en el piso y suéltalo: ¡el carretel anda solo! La energía quedó guardada en la gomita, como en una batería."] }, at: "Casa del futuro", m: "papel grande, lápices de colores", p: ["Dibuja una casa que produce su propia energía, con paneles solares, una batería y un cargador inalámbrico.", "Muestra con flechas adónde va la energía durante el día y durante la noche.", "Pinta la bombilla 29 del panel."], q: "¿Qué invento de energía te gustaría que existiera cuando seas grande?" } },

{ e: "🏆", art: { b: "🏆", s: ["💡", "⚡", "🧲", "🎉"], c: ["#2A2350", "#D4A82C"] },
pt: { h: "Na última noite, só faltava uma lâmpada para pintar no painel. O vovô preparou massinhas de duas cores e uma surpresa: um LED. “Hoje vamos acender a luz com massinha”, anunciou. Quando o LED brilhou, Nina e Leo gritaram tão alto que o Pipoca saiu correndo.", t: "Formatura no Laboratório das Faíscas", f: "Em 30 dias, vocês descobriram que a eletricidade está nos raios, nos ímãs, nas pilhas, no nosso corpo e em quase tudo o que usamos. Ela é feita de elétrons em movimento, viaja por circuitos fechados e pode virar luz, calor, som e movimento. E precisa sempre de respeito e cuidado.", x: "A massinha com sal conduz eletricidade, e a massinha com açúcar quase não conduz! Com as duas, dá para montar circuitos que se moldam como esculturas.", s: ["Condutores deixam a eletricidade passar; isolantes seguram a eletricidade no caminho certo.", "Ímãs e eletricidade são parentes: um pode criar o outro.", "A energia do futuro pode ser mais limpa, e cada pessoa ajuda economizando e cuidando do planeta."], ex: { t: "Circuito de massinha", m: "massinha caseira com bastante sal (condutora), massinha feita com açúcar (isolante), duas pilhas AA num suporte ou presas com fita, um LED, um adulto", p: ["Faça duas bolas de massinha salgada e separe-as com um pedaço de massinha de açúcar no meio.", "Com um adulto, encoste um fio da pilha em cada bola salgada e espete as duas “perninhas” do LED, uma em cada bola.", "O LED acende! Se não acender, vire o LED. Agora junte as duas bolas salgadas: ele apaga, porque a eletricidade pega o atalho."] }, at: "Diploma de cientista", m: "cartolina, lápis dourado ou amarelo", p: ["Pinte a última lâmpada do painel: o laboratório está todo aceso!", "Escreva as três descobertas de que você mais gostou.", "Faça uma apresentação para a família mostrando seu experimento favorito."], q: "De tudo o que você aprendeu sobre eletricidade, o que mais te surpreendeu?" },
en: { h: "On the last night, there was just one bulb left to color on the chart. Grandpa made play dough in two colors and had a surprise: an LED. “Tonight we'll turn on a light with play dough,” he announced. When the LED glowed, Nina and Leo shouted so loudly that Popcorn ran off.", t: "Spark Lab graduation", f: "In 30 days, you discovered that electricity is in lightning, magnets, batteries, our bodies and almost everything we use. It's made of moving electrons, travels through closed circuits and can become light, heat, sound and motion. And it always deserves respect and care.", x: "Salty play dough conducts electricity, and sugary play dough barely does! With both, you can build circuits that you shape like sculptures.", s: ["Conductors let electricity through; insulators keep it on the right path.", "Magnets and electricity are relatives: each one can create the other.", "The energy of the future can be cleaner, and everyone helps by saving energy and caring for the planet."], ex: { t: "Play dough circuit", m: "homemade play dough with lots of salt (conductive), play dough made with sugar (insulating), two AA batteries in a holder or taped together, an LED, a grown-up", p: ["Make two balls of salty dough and separate them with a piece of sugar dough in between.", "With a grown-up, touch one battery wire to each salty ball and push the LED's two legs in, one into each ball.", "The LED lights up! If it doesn't, flip the LED around. Now push the two salty balls together: it goes out, because the electricity takes the shortcut."] }, at: "Scientist diploma", m: "poster board, a gold or yellow pencil", p: ["Color the last bulb on the chart: the whole lab is lit!", "Write the three discoveries you liked best.", "Give your family a presentation showing your favorite experiment."], q: "Of everything you learned about electricity, what surprised you most?" },
es: { h: "En la última noche, solo faltaba una bombilla por pintar en el panel. El abuelo preparó plastilinas de dos colores y una sorpresa: un LED. “Hoy vamos a encender la luz con plastilina”, anunció. Cuando el LED brilló, Nina y Leo gritaron tan fuerte que Palomita salió corriendo.", t: "Graduación en el Laboratorio de las Chispas", f: "En 30 días descubrieron que la electricidad está en los rayos, los imanes, las pilas, nuestro cuerpo y casi todo lo que usamos. Está hecha de electrones en movimiento, viaja por circuitos cerrados y puede convertirse en luz, calor, sonido y movimiento. Y siempre merece respeto y cuidado.", x: "¡La plastilina con sal conduce la electricidad, y la plastilina con azúcar casi no conduce! Con las dos se pueden armar circuitos que se moldean como esculturas.", s: ["Los conductores dejan pasar la electricidad; los aislantes la mantienen en el camino correcto.", "Los imanes y la electricidad son parientes: uno puede crear al otro.", "La energía del futuro puede ser más limpia, y cada persona ayuda ahorrando y cuidando el planeta."], ex: { t: "Circuito de plastilina", m: "plastilina casera con mucha sal (conductora), plastilina hecha con azúcar (aislante), dos pilas AA en un portapilas o unidas con cinta, un LED, un adulto", p: ["Haz dos bolas de plastilina salada y sepáralas con un pedazo de plastilina de azúcar en el medio.", "Con un adulto, apoya un cable de las pilas en cada bola salada y clava las dos “patitas” del LED, una en cada bola.", "¡El LED se enciende! Si no se enciende, da vuelta el LED. Ahora junta las dos bolas saladas: se apaga, porque la electricidad toma el atajo."] }, at: "Diploma de científico", m: "cartulina, lápiz dorado o amarillo", p: ["Pinta la última bombilla del panel: ¡todo el laboratorio está encendido!", "Escribe los tres descubrimientos que más te gustaron.", "Haz una presentación para tu familia mostrando tu experimento favorito."], q: "De todo lo que aprendiste sobre la electricidad, ¿qué fue lo que más te sorprendió?" } },
];
